const snippets={"Python": ["", "", "class Solution:", "", "    def longestValidParentheses(self, s: str) -> int:", "        n = len(s)", "        f = [0] * (n + 1)", "        for (i, c) in enumerate(s, 1):", "            if c == ')':", "                if i > 1 and s[i - 2] == '(':", "                    f[i] = f[i - 2] + 2", "                else:", "                    j = i - f[i - 1] - 1", "                    if j and s[j - 1] == '(':", "                        f[i] = f[i - 1] + 2 + f[j - 1]", "        return max(f)"], "Java": ["import java.util.*;", "class Solution {", "    public int longestValidParentheses(String s) {", "        int n = s.length();", "        int[] f = new int[n + 1];", "        int ans = 0;", "        for (int i = 2; i <= n; ++i) {", "            if (s.charAt(i - 1) == ')') {", "                if (s.charAt(i - 2) == '(') {", "                    f[i] = f[i - 2] + 2;", "                } else {", "                    int j = i - f[i - 1] - 1;", "                    if (j > 0 && s.charAt(j - 1) == '(') {", "                        f[i] = f[i - 1] + 2 + f[j - 1];", "                    }", "                }", "                ans = Math.max(ans, f[i]);", "            }", "        }", "        return ans;", "    }", "}"]};
